import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { MaterialIcon } from './MaterialIcon';
import { UniverseBackLink } from './UniverseBackLink';
import { VybeLogo } from './VybeLogo';
import './AcademicApp.css';

type Role = 'STUDENT'|'TEACHER'|'DIRECTOR'|'ACADEMIC_ADMIN';
type Me = { profile:{id:string;displayName:string;username:string;avatarUrl:string;bio:string;courseOfStudy:string};roles:Role[];canAccessTeacherArea:boolean;canManageAcademic:boolean;canBootstrapAcademicAdmin:boolean;pendingInvite?:{id:string;name:string;message:string}|null };
type Discipline = {id:string;name:string;code:string;description:string;teachers:{name:string;username:string}[];nextLesson?:{title:string;startAt:string;location:string}|null;nextExam?:{title:string;examAt:string}|null;pendingCount:number};
type Item = Record<string,any>;
const api = async <T,>(path:string, init?:RequestInit):Promise<T> => { const response=await fetch(path,{credentials:'same-origin',...init});const body=await response.json().catch(()=>null);if(!response.ok)throw new Error(body?.error??'Não foi possível concluir.');return body as T; };
const json = (body:unknown):RequestInit=>({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
const fileDataUrl=(file:File)=>new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==='string'?resolve(reader.result):reject(new Error('Não foi possível ler o arquivo.'));reader.onerror=()=>reject(new Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file)});
const dateLabel=(value?:string)=>value?new Intl.DateTimeFormat('pt-BR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—';
const disciplineTeacherLabel=(teachers:Discipline['teachers'])=>teachers.length?teachers.map(teacher=>`Prof. ${teacher.name}`).join(', '):'Professor não informado';
const dateOnly=(value?:string)=>value?new Intl.DateTimeFormat('pt-BR',{dateStyle:'long'}).format(new Date(value)):'—';
const dateTimeInput=(value?:string)=>value?new Date(new Date(value).getTime()-new Date(value).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
const gradeEquivalence=(score:number,maxScore:number)=>{const percentage=maxScore>0?(score/maxScore)*100:0;const letter=percentage>=90?'A':percentage>=80?'B':percentage>=70?'C':percentage>=60?'D':'F';const gpa=letter==='A'?4:letter==='B'?3:letter==='C'?2:letter==='D'?1:0;const description=letter==='A'?'Excelente':letter==='B'?'Muito bom / Bom':letter==='C'?'Satisfatório / Médio':letter==='D'?'Abaixo da média / Mínimo para aprovação':'Reprovado';return {percentage,letter,gpa,description};};
const gradeScale=[['A','90%–100%','4,0','Excelente'],['B','80%–89%','3,0','Muito bom / Bom'],['C','70%–79%','2,0','Satisfatório / Médio'],['D','60%–69%','1,0','Abaixo da média / Mínimo para aprovação'],['F','Abaixo de 60%','0,0','Reprovado']];

const normalizeAcademicDates=(body:Record<string,any>)=>{for(const key of ['startAt','endAt','dueAt','opensAt','examAt'])if(typeof body[key]==='string'&&body[key])body[key]=new Date(body[key]).toISOString();return body};
function academicRoleLabel(roles:Role[]){return roles.includes('ACADEMIC_ADMIN')?'ADM':roles.includes('DIRECTOR')?'Diretor(a)':roles.includes('TEACHER')?'Professor(a)':'Aluno(a)'}
function Avatar({name,url}:{name:string;url?:string}){return <span className="academic-avatar">{url?<img src={url} alt=""/>:name.slice(0,1).toUpperCase()}</span>}
function Empty({children}:{children:string}){return <div className="academic-empty"><span><MaterialIcon name="school"/></span><p>{children}</p></div>}
function Section({title,icon,action,children}:{title:string;icon:string;action?:ReactNode;children:ReactNode}){return <section className="academic-section"><header><h2><MaterialIcon name={icon}/>{title}</h2>{action}</header>{children}</section>}

function AcademicProfileEditor({profile,onSaved}:{profile:Me['profile'];onSaved:(data:{avatarUrl:string;courseOfStudy:string})=>void}){
 const [course,setCourse]=useState(profile.courseOfStudy??'');const [photo,setPhoto]=useState('');const [photoName,setPhotoName]=useState('');const [saving,setSaving]=useState(false);const [error,setError]=useState('');
 async function submit(event:FormEvent){event.preventDefault();setSaving(true);setError('');try{const result=await api<{avatarUrl:string;courseOfStudy:string}>('/api/academic/profile',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({courseOfStudy:course,...(photo?{photo}:{})})});onSaved(result);setPhoto('');setPhotoName('');}catch(reason){setError(reason instanceof Error?reason.message:'Não foi possível salvar seu perfil.');}finally{setSaving(false);}}
 return <form className="academic-profile-editor" onSubmit={(event)=>void submit(event)}><div className="academic-profile"><Avatar name={profile.displayName} url={photo||profile.avatarUrl}/><div><h2>{profile.displayName}</h2><p>@{profile.username}</p><small>Perfil acadêmico</small></div></div><label className="academic-photo-control"><span className="academic-photo-label">Foto do perfil</span><span className="academic-photo-picker"><span className="academic-photo-picker-icon"><MaterialIcon name="add_a_photo"/></span><span className="academic-photo-picker-copy"><strong>{photoName||'Escolha uma nova foto'}</strong><small>{photoName?'Prévia atualizada acima':'JPG, PNG ou WebP · até 2 MB'}</small></span><span className="academic-photo-picker-action">Procurar</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event)=>{const file=event.currentTarget.files?.[0];event.currentTarget.value='';if(!file)return;if(file.size>2*1024*1024){setError('A foto deve ter no máximo 2 MB.');return;}void fileDataUrl(file).then((data)=>{setPhoto(data);setPhotoName(file.name);setError('');}).catch(()=>setError('Não foi possível abrir esta imagem.'));}}/></span>{!photoName&&<small className="academic-photo-hint">Sua foto será exibida no perfil desta comunidade.</small>}</label><label>Curso ou matéria que está fazendo<input value={course} onChange={(event)=>setCourse(event.currentTarget.value)} maxLength={120} placeholder="Ex.: Medicina, História ou Biologia"/></label>{error&&<p className="academic-inline-error" role="alert">{error}</p>}<button type="submit" disabled={saving}>{saving?'Salvando…':'Salvar perfil'}</button></form>;
}

type AcademicSubmit=(e:FormEvent<HTMLFormElement>,path:string,after?:()=>void)=>void;
function ActivitiesPage({activities,teacherData,canManage,busy,submit}:{activities:Item[];teacherData:Item|null;canManage:boolean;busy:boolean;submit:AcademicSubmit}){
 const disciplines=(teacherData?.disciplines??[]) as Item[];const items=(teacherData?.assignments??[]) as Item[];
 return <div className="academic-page-stack">{canManage&&<Section title="Criar atividade" icon="add_box"><form onSubmit={e=>submit(e,'/api/academic/teacher/assignments')}><select name="disciplineId" required><option value="">Disciplina</option>{disciplines.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select><input name="title" placeholder="Título da atividade" required minLength={2}/><textarea name="instructions" placeholder="Descreva o que os alunos devem realizar" required/><input name="dueAt" type="datetime-local" required/><input name="maxScore" type="number" min="0.01" step="0.1" placeholder="Nota máxima" required/><label><input name="allowText" type="checkbox" defaultChecked/> Permitir entrega em texto</label><label><input name="allowFile" type="checkbox"/> Permitir entrega de arquivo</label><input name="academicFile" type="file" accept=".pdf,.docx,.pptx,.xlsx,.xls,image/png,image/jpeg,image/webp"/><button disabled={busy||!disciplines.length}>Publicar atividade</button></form>{!disciplines.length&&<p className="academic-muted">Você precisa estar vinculado a uma disciplina para publicar atividades.</p>}</Section>}
 <Section title={canManage?'Atividades publicadas':'Atividades'} icon="assignment">{canManage?(items.length?<div className="academic-list">{items.map(a=><article key={a._id} className="academic-row"><span className="academic-row-icon"><MaterialIcon name="assignment"/></span><div><strong>{a.title}</strong><p>{disciplines.find(d=>d.id===String(a.disciplineId))?.name??'Disciplina'} · Entrega até {dateLabel(a.dueAt)}</p><small>{a.instructions}</small></div></article>)}</div>:<Empty>Nenhuma atividade publicada nas suas disciplinas.</Empty>):activities.length?<div className="academic-list">{activities.map(a=><article key={a._id} className="academic-row"><span className="academic-row-icon"><MaterialIcon name="assignment"/></span><div><strong>{a.title}</strong><p>{a.disciplineName} · Entrega até {dateLabel(a.dueAt)}</p>{a.instructions&&<small>{a.instructions}</small>}</div><span className={`academic-status ${a.submission?.status==='graded'?'done':''}`}>{a.submission?.status==='graded'?'Corrigida':a.submission?'Entregue':new Date(a.dueAt)<new Date()?'Atrasada':'Pendente'}</span>{!a.submission&&<form className="academic-inline-submit" onSubmit={e=>submit(e,`/api/academic/assignments/${a._id}/submit`)}><textarea name="textContent" placeholder="Escreva sua entrega..." maxLength={10000}/>{a.allowFile&&<input name="academicFile" type="file" accept=".pdf,.docx,.pptx,.xlsx,.xls,image/png,image/jpeg,image/webp"/>}<button disabled={busy}>Enviar</button></form>}</article>)}</div>:<Empty>Nenhuma atividade pendente.</Empty>}</Section></div>;
}
function StudentExamCard({ item, refresh }: { item: Item; refresh: () => void }) {
 const questions = (item.questions ?? []) as { prompt: string }[];
 const [submission, setSubmission] = useState<Item | null>(item.submission ?? null);
 const [saving, setSaving] = useState(false);
 const [error, setError] = useState('');
 async function submitExam(event: FormEvent<HTMLFormElement>) {
  event.preventDefault();
  const values = Object.fromEntries(new FormData(event.currentTarget).entries());
  const body = questions.length
   ? { answers: questions.map((_, index) => ({ response: String(values[`answer_${index}`] ?? '') })) }
   : { responseText: String(values.responseText ?? '') };
  setSaving(true); setError('');
  try {
   const result = await api<Item>(`/api/academic/exams/${item._id ?? item.id}/submit`, json(body));
   setSubmission(result); refresh();
  } catch (reason) {
   setError(reason instanceof Error ? reason.message : 'Não foi possível enviar sua prova.');
  } finally { setSaving(false); }
 }
 return <article className="academic-row academic-exam-card">
  <span className="academic-row-icon exam"><MaterialIcon name="event"/></span>
  <div className="academic-exam-content">
   <strong>{item.title}</strong>
   <p>{item.disciplineName} · {dateLabel(item.examAt)}{item.location ? ` · ${item.location}` : ''}</p>
   {item.description && <small>{item.description}</small>}
   {item.instructions && <small>{item.instructions}</small>}
   {item.attachment?.url && <a href={item.attachment.url}>{item.attachment.name}</a>}
   {submission ? <div className="academic-exam-submitted"><MaterialIcon name="check_circle"/><span>Prova enviada em {dateLabel(submission.submittedAt)}.</span></div> :
    <form className="academic-exam-attempt" onSubmit={(event) => void submitExam(event)}>
     {questions.length ? questions.map((question, index) => <label key={`${question.prompt}-${index}`}><strong>{index + 1}. {question.prompt}</strong><textarea name={`answer_${index}`} placeholder="Escreva sua resposta" required maxLength={5000}/></label>) :
      <textarea name="responseText" placeholder="Escreva sua resposta para esta prova" required maxLength={10000}/>}
     <button disabled={saving}>{saving ? 'Enviando…' : 'Enviar prova'}</button>
     {error && <p className="academic-inline-error" role="alert">{error}</p>}
    </form>}
  </div>
 </article>;
}
function ExamsPage({ exams, teacherData, canManage, busy, submit, refresh }: { exams: Item[]; teacherData: Item | null; canManage: boolean; busy: boolean; submit: AcademicSubmit; refresh: () => void }) {
 const disciplines = (teacherData?.disciplines ?? []) as Item[];
 const items = (teacherData?.exams ?? []) as Item[];
 const responses = (teacherData?.examSubmissions ?? []) as Item[];
 const published = canManage ? (items.length ? <div className="academic-list">{items.map(item => <article key={item._id} className="academic-row"><span className="academic-row-icon exam"><MaterialIcon name="event"/></span><div><strong>{item.title}</strong><p>{disciplines.find(d => d.id === String(item.disciplineId))?.name ?? 'Disciplina'} · {dateLabel(item.examAt)}{item.location ? ` · ${item.location}` : ''}</p><small>{item.description || item.instructions}</small></div></article>)}</div> : <Empty>Nenhuma prova publicada nas suas disciplinas.</Empty>) : (exams.length ? <div className="academic-list">{exams.map(item => <StudentExamCard key={item.id ?? item._id} item={item} refresh={refresh}/>)}</div> : <Empty>Você não possui provas próximas.</Empty>);
 return <div className="academic-page-stack">
  {canManage && <Section title="Criar prova" icon="fact_check"><form onSubmit={event => submit(event, '/api/academic/teacher/exams')}><select name="disciplineId" required><option value="">Disciplina</option>{disciplines.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}</select><input name="title" placeholder="Título da prova" required minLength={2}/><input name="examAt" type="datetime-local" required/><input name="location" placeholder="Sala ou local"/><input name="maxScore" type="number" min="0.01" step="0.1" placeholder="Nota máxima" required/><textarea name="description" placeholder="Conteúdo e instruções da prova"/><textarea name="questionsText" placeholder="Questões da prova (uma por linha)" required maxLength={42000}/><input name="academicFile" type="file" accept=".pdf,.docx,.pptx,.xlsx,.xls,image/png,image/jpeg,image/webp"/><button disabled={busy || !disciplines.length}>Publicar prova</button></form>{!disciplines.length && <p className="academic-muted">Você precisa estar vinculado a uma disciplina para publicar provas.</p>}</Section>}
  <Section title={canManage ? 'Provas publicadas' : 'Provas'} icon="fact_check">{published}</Section>
  {canManage && <Section title="Respostas enviadas pelos alunos" icon="assignment"><div className="academic-list">{responses.length ? responses.map(response => <article className="academic-row academic-exam-response" key={response.id}><div><strong>{response.student?.displayName ?? 'Aluno'} · {response.examTitle}</strong><p>@{response.student?.username ?? 'membro'} · Enviada em {dateLabel(response.submittedAt)}</p>{response.answers?.map((answer: Item, index: number) => <small key={`${response.id}-${index}`}><b>{answer.prompt}</b><br/>{answer.response}</small>)}{response.responseText && <small>{response.responseText}</small>}</div></article>) : <Empty>Nenhuma resposta de prova recebida.</Empty>}</div></Section>}
 </div>;
}

export function AcademicApp({community}:{community:string}){
 const path=window.location.pathname;const [me,setMe]=useState<Me|null>(null);const [disciplines,setDisciplines]=useState<Discipline[]>([]);const [enrolledDisciplines,setEnrolledDisciplines]=useState<Discipline[]>([]);const [personalDisciplines,setPersonalDisciplines]=useState<Discipline[]>([]);const [activities,setActivities]=useState<Item[]>([]);const [exams,setExams]=useState<Item[]>([]);const [grades,setGrades]=useState<Item[]>([]);const [notices,setNotices]=useState<Item[]>([]);const [notificationsOpen,setNotificationsOpen]=useState(false);const notificationsRef=useRef<HTMLDivElement>(null);const [todayLessons,setTodayLessons]=useState<Item[]>([]);const [teacherData,setTeacherData]=useState<Item|null>(null);const [detail,setDetail]=useState<Item|null>(null);const [members,setMembers]=useState<Item[]>([]);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');
 const load=useCallback(async()=>{try{const m=await api<Me>('/api/academic/me');setMe(m);const [d,a,e,g,n,today,mine,personal]=await Promise.all([api<Discipline[]>('/api/academic/disciplines'),api<Item[]>('/api/academic/activities'),api<Item[]>('/api/academic/exams'),api<Item[]>('/api/academic/grades'),api<Item[]>('/api/academic/notices'),api<Item[]>('/api/academic/today'),path==='/academico/disciplinas'?api<Discipline[]>('/api/academic/disciplines?scope=enrolled'):Promise.resolve(null),path==='/academico'||path==='/academico/'?api<Discipline[]>('/api/academic/disciplines?scope=mine'):Promise.resolve(null)]);setDisciplines(d);if(mine)setEnrolledDisciplines(mine);if(personal)setPersonalDisciplines(personal);setActivities(a);setExams(e);setGrades(g);setNotices(n);setTodayLessons(today);if(['/academico/professor','/academico/atividades','/academico/provas'].includes(path)&&m.canAccessTeacherArea)setTeacherData(await api<Item>('/api/academic/teacher'));if(path==='/academico/admin'&&m.canManageAcademic)setMembers(await api('/api/academic/admin/members'));if(path.startsWith('/academico/disciplinas/'))setDetail(await api<Item>(`/api/academic/disciplines/${path.split('/').pop()}`));}catch(e){setError(e instanceof Error?e.message:'Não foi possível carregar o Acadêmico.');}},[path]);
 useEffect(()=>{void load()},[load]);
 useEffect(()=>{if(!notificationsOpen)return;const closeOutside=(event:PointerEvent)=>{if(!notificationsRef.current?.contains(event.target as Node))setNotificationsOpen(false)};const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape')setNotificationsOpen(false)};document.addEventListener('pointerdown',closeOutside);document.addEventListener('keydown',closeOnEscape);return()=>{document.removeEventListener('pointerdown',closeOutside);document.removeEventListener('keydown',closeOnEscape)}},[notificationsOpen]);
 const submit=async(e:FormEvent<HTMLFormElement>,path:string,after?:()=>void)=>{e.preventDefault();setBusy(true);setError('');const formElement=e.currentTarget;const form=new FormData(formElement);const body:Record<string,any>={...Object.fromEntries(form.entries())};if(formElement.querySelector('[name="disciplineIds"]'))body.disciplineIds=form.getAll('disciplineIds').filter((value):value is string=>typeof value==='string'&&Boolean(value));if(path.endsWith('/assignments')){body.allowText=form.has('allowText');body.allowFile=form.has('allowFile');}if(path.endsWith('/teacher/exams')){body.questions=String(body.questionsText??'').split(/\r?\n/).map(question=>question.trim()).filter(Boolean);delete body.questionsText;}try{const file=formElement.querySelector<HTMLInputElement>('input[name="academicFile"]')?.files?.[0];if(file){const uploaded=await api<Item>('/api/academic/files',json({name:file.name,data:await fileDataUrl(file)}));body.attachment=uploaded;body.allowFile=true;}delete body.academicFile;normalizeAcademicDates(body);await api(path,json(body));setMessage('Informações salvas.');formElement.reset();after?.();await load();}catch(err){setError(err instanceof Error?err.message:'Não foi possível salvar.')}finally{setBusy(false)}};
 const nav=[['/academico','home','Início'],['/academico/disciplinas','menu_book','Disciplinas'],['/academico/atividades','assignment','Atividades'],['/academico/provas','fact_check','Provas'],['/academico/notas','bar_chart','Notas'],['/academico/perfil','person','Perfil']];
 const activePath=path==='/academico'||path==='/academico/'?'/academico':path;
 const title=path.includes('/disciplinas')?'Disciplinas':path.includes('/atividades')?'Atividades':path.includes('/provas')?'Provas':path.includes('/notas')?'Notas':path.includes('/perfil')?'Perfil':path.includes('/professor')?'Área do Professor':path.includes('/admin')?'Gestão acadêmica':'Início';
 const profile=me?.profile;
 const ownLessons=todayLessons;
 const pending=activities.filter(a=>!a.submission||a.submission.status!=='graded');
 const noticeLabel=(n:Item)=>n.type==='academic_grade'?'Uma nota foi lançada para você.':n.type==='academic_submission'?'Uma atividade foi enviada.':'Uma atualização acadêmica foi publicada.';
 let content:ReactNode;
 if(error&&!me) content=<div className="academic-error"><MaterialIcon name="lock"/><h2>Acadêmico indisponível</h2><p>{error}</p></div>;
 else if(path==='/academico/professor'&&!me?.canAccessTeacherArea) content=<div className="academic-error"><MaterialIcon name="lock"/><h2>Área do Professor restrita</h2><p>Seu perfil ainda não recebeu autorização acadêmica nesta comunidade.</p><a href="/academico">Voltar ao Acadêmico</a></div>;
 else if(path==='/academico/professor') content=<TeacherHome data={teacherData} busy={busy} error={error} submit={submit} refresh={load}/>;
 else if(path==='/academico/admin'&&!me?.canManageAcademic) content=<div className="academic-error"><MaterialIcon name="lock"/><h2>Gestão acadêmica restrita</h2><p>Esta área está disponível apenas para Academic Admin.</p><a href="/academico">Voltar ao Acadêmico</a></div>;
 else if(path==='/academico/admin') content=<AdminHome disciplines={disciplines} members={members} busy={busy} error={error} submit={submit} refresh={load}/>;
 else if(path.startsWith('/academico/disciplinas/')&&detail) content=<DisciplineDetail data={detail} busy={busy} error={error} submit={submit}/>;
 else if(path==='/academico/disciplinas') content=<StudentDisciplines disciplines={enrolledDisciplines} refresh={load}/>;
 else if(path==='/academico/atividades') content=<ActivitiesPage activities={activities} teacherData={teacherData} canManage={Boolean(me?.canAccessTeacherArea)} busy={busy} submit={submit}/>;
 else if(path==='/academico/provas') content=<ExamsPage exams={exams} teacherData={teacherData} canManage={Boolean(me?.canAccessTeacherArea)} busy={busy} submit={submit} refresh={load}/>;
 else if(path==='/academico/notas') content=<div className="academic-page-stack"><Section title="Escala de notas e equivalência" icon="grade"><div className="academic-grade-scale">{gradeScale.map(([letter,range,gpa,label])=><div className="academic-grade-scale-item" key={letter}><b>{letter}</b><span>{range}</span><strong>{gpa} GPA</strong><small>{label}</small></div>)}</div></Section><Section title="Minhas notas" icon="bar_chart">{grades.length?<div className="academic-list">{grades.map(g=>{const equivalent=gradeEquivalence(Number(g.score),Number(g.maxScore));return <article className="academic-grade-row" key={g.id}><div><strong>{g.disciplineName}</strong><p>{g.title}</p><small>{equivalent.percentage.toFixed(1).replace('.',',')}% · Conceito {equivalent.letter} ({equivalent.description}) · {equivalent.gpa.toFixed(1).replace('.',',')} pontos GPA</small>{g.feedback&&<small>{g.feedback}</small>}</div><b>{g.score} <small>/ {g.maxScore}</small></b></article>})}</div>:<Empty>Suas notas aparecerão aqui.</Empty>}</Section></div>;
 else if(path==='/academico/perfil'&&profile) content=<Section title="Perfil acadêmico" icon="person"><AcademicProfileEditor profile={profile} onSaved={(saved)=>{setMe((current)=>current?{...current,profile:{...current.profile,...saved}}:current);setMessage('Perfil acadêmico atualizado.');setError('');}}/><p className="academic-muted">A foto e o curso ficam neste perfil acadêmico da comunidade. Seu perfil principal do VYBE não é alterado.</p>{me?.pendingInvite&&<div className="academic-invite"><h3>Convite para professor</h3><p>{me.pendingInvite.message||`Você recebeu um convite para atuar como professor${me.pendingInvite.name?` (${me.pendingInvite.name})`:''}.`}</p><button onClick={async()=>{try{await api(`/api/academic/invites/${me.pendingInvite!.id}/accept`,{method:'POST'});await load();setMessage('Convite aceito. Área do Professor liberada.')}catch(e){setError(e instanceof Error?e.message:'Não foi possível aceitar o convite.')}}}>Aceitar convite</button></div>}</Section>;
 else content=<Home community={community} profile={profile} lessons={ownLessons} disciplines={personalDisciplines} pending={pending} exams={exams} roles={me?.roles??[]} bootstrap={me?.canBootstrapAcademicAdmin??false}/>;
 return <div className="academic-app"><aside className="academic-sidebar"><a href="/academico" className="academic-brand"><VybeLogo variant="symbol" className="academic-brand-mark"/><span><b>VYBE</b><small>Acadêmico</small></span></a><div className="academic-community"><span><MaterialIcon name="groups"/></span><strong>{community}</strong><MaterialIcon name="expand_more"/></div><nav>{nav.map(([href,icon,label])=><a href={href} key={href} className={activePath===href?'active':''}><MaterialIcon name={icon}/>{label}</a>)}</nav><UniverseBackLink className="academic-universe"/></aside><main className="academic-main"><header className="academic-topbar"><div><h1>{title}</h1><p>{title==='Início'?'Seu percurso, seu conhecimento, seu futuro.':community}</p></div><div className="academic-top-search"><MaterialIcon name="search"/><input placeholder="Buscar disciplinas, atividades, provas..." onKeyDown={e=>{if(e.key==='Enter'&&e.currentTarget.value)window.location.href=`/academico/disciplinas?q=${encodeURIComponent(e.currentTarget.value)}`}}/></div><div className="academic-notification-wrap" ref={notificationsRef}><button className={`academic-bell ${notices.length?'has-notices':''}`} type="button" aria-label="Notificações" aria-expanded={notificationsOpen} aria-controls="academic-notifications-panel" onClick={()=>setNotificationsOpen(open=>!open)}><MaterialIcon name="notifications"/></button>{notificationsOpen&&<section className="academic-notifications-panel" id="academic-notifications-panel" aria-label="Notificações acadêmicas"><header><h2>Notificações</h2><button type="button" aria-label="Fechar notificações" onClick={()=>setNotificationsOpen(false)}><MaterialIcon name="close"/></button></header>{notices.length?<div className="academic-notification-list">{notices.slice(0,10).map(notice=><a className="academic-notification-item" href={notice.type==='academic_grade'?'/academico/notas':notice.type==='academic_submission'?'/academico/atividades':'/academico/disciplinas'} key={notice.id} onClick={()=>setNotificationsOpen(false)}><span className="academic-notification-icon"><MaterialIcon name={notice.type==='academic_grade'?'bar_chart':notice.type==='academic_submission'?'assignment':'campaign'}/></span><span><strong>{noticeLabel(notice)}</strong><small>{dateLabel(notice.createdAt)}</small></span><MaterialIcon name="chevron_right"/></a>)}</div>:<div className="academic-notification-empty"><MaterialIcon name="notifications_off"/><p>Nenhuma novidade por enquanto.</p></div>}</section>}</div><a href="/academico/perfil" className="academic-user"><Avatar name={profile?.displayName??'?'} url={profile?.avatarUrl}/><span><b>{profile?.displayName}</b><small>{me?academicRoleLabel(me.roles):'Aluno(a)'}</small></span></a></header><div className="academic-content">{error&&<div className="academic-inline-error">{error}</div>}{message&&<div className="academic-success">{message}</div>}{content}</div></main>{path==='/academico'||path==='/academico/'?<aside className="academic-right"><Section title="Avisos" icon="campaign" action={<a href="/academico/atividades">Ver todos</a>}>{notices.length?notices.slice(0,3).map(n=><div className="academic-notice" key={n.id}><i/><span>{noticeLabel(n)}<small>{dateLabel(n.createdAt)}</small></span></div>):<p className="academic-muted">Nenhum aviso acadêmico por enquanto.</p>}</Section><Section title="Calendário acadêmico" icon="calendar_month"><MiniCalendar exams={exams} lessons={ownLessons}/></Section><Section title="Resumo da semana" icon="bar_chart"><div className="academic-summary"><div><b>{ownLessons.length}</b><small>Aulas próximas</small></div><div><b>{pending.length}</b><small>Atividades</small></div><div><b>{exams.length}</b><small>Provas</small></div></div></Section></aside>:null}</div>;
}

function Home({community,profile,lessons,disciplines,pending,exams,roles,bootstrap}:{community:string;profile?:Me['profile'];lessons:Item[];disciplines:Discipline[];pending:Item[];exams:Item[];roles:Role[];bootstrap:boolean}){
 const greeting=new Date().getHours()<12?'Bom dia':new Date().getHours()<18?'Boa tarde':'Boa noite';
 return <div className="academic-home"><section className="academic-hero"><small>{community.toUpperCase()}</small><h2>{greeting}, {profile?.displayName.split(' ')[0]??'estudante'}.</h2><h3>Seu ambiente acadêmico em {community}.</h3><p>Acompanhe disciplinas, acesse conteúdos e fique por dentro da sua jornada acadêmica.</p></section><div className="academic-top-cards"><Section title="Hoje" icon="calendar_today" action={<a href="/academico/disciplinas">Ver agenda</a>}>{lessons.length?lessons.slice(0,3).map(l=><div className="academic-compact-row" key={l.title}><b>{new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(l.startAt))}</b><span><strong>{l.discipline}</strong><small>{l.title} · {l.location||'Local a definir'}</small></span></div>):<Empty>Você não tem aulas próximas.</Empty>}</Section><Section title="Próximas provas" icon="fact_check" action={<a href="/academico/provas">Ver todas</a>}>{exams.length?exams.slice(0,3).map(e=><div className="academic-compact-row" key={e._id}><span className="academic-row-icon exam"><MaterialIcon name="menu_book"/></span><span><strong>{e.title}</strong><small>{e.disciplineName} · {dateOnly(e.examAt)}</small></span></div>):<Empty>Você não possui provas próximas.</Empty>}</Section><Section title="Pendências" icon="task_alt" action={<a href="/academico/atividades">Ver todas</a>}>{pending.length?pending.slice(0,3).map(a=><div className="academic-compact-row" key={a._id}><span className="academic-row-icon warn"><MaterialIcon name="assignment"/></span><span><strong>{a.title}</strong><small>{a.disciplineName} · Prazo {dateOnly(a.dueAt)}</small></span></div>):<Empty>Nenhuma atividade pendente.</Empty>}</Section></div><Section title="Minhas disciplinas" icon="menu_book" action={<a href="/academico/disciplinas">Ver todas</a>}>{disciplines.length?<div className="academic-discipline-grid">{disciplines.slice(0,4).map(d=><a href={`/academico/disciplinas/${d.id}`} className="academic-discipline-card" key={d.id}><div className="academic-discipline-art"><MaterialIcon name="school"/></div><h3>{d.name}</h3><p>{profile?.displayName.split(/\s+/)[0]??'Aluno'} · {disciplineTeacherLabel(d.teachers)}</p>{d.nextLesson&&<div className="academic-next"><small>Próxima aula</small><strong>{d.nextLesson.title}</strong><span>{dateLabel(d.nextLesson.startAt)}</span></div>}</a>)}</div>:<Empty>Você ainda não está vinculado a nenhuma disciplina.</Empty>}</Section>{(roles.includes('TEACHER')||roles.includes('DIRECTOR')||roles.includes('ACADEMIC_ADMIN'))&&<section className="academic-teacher-cta"><div><MaterialIcon name="school"/><span><b>Área do Professor</b><small>Gerencie disciplinas, aulas e avaliações vinculadas a você.</small></span></div><a href="/academico/professor">Entrar na Área do Professor <MaterialIcon name="arrow_forward"/></a></section>}{roles.includes('ACADEMIC_ADMIN')&&<a className="academic-admin-link" href="/academico/admin">Gestão acadêmica</a>}{bootstrap&&<SetupAdmin/>}</div>
}
function MiniCalendar({exams,lessons}:{exams:Item[];lessons:Item[]}){const date=new Date();const month=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(date);const count=new Date(date.getFullYear(),date.getMonth()+1,0).getDate();return <div className="academic-mini"><b>{month}</b><div>{Array.from({length:count},(_,i)=><span className={i+1===date.getDate()?'today':''} key={i}>{i+1}</span>)}</div><small>{exams.length} provas · {lessons.length} aulas próximas</small></div>}
function SetupAdmin(){const [members,setMembers]=useState<Item[]>([]);const [profileId,setProfileId]=useState('');const [error,setError]=useState('');useEffect(()=>{void api<Item[]>('/api/academic/admin/members').then(setMembers).catch(()=>undefined)},[]);return <section className="academic-setup"><h3>Configuração inicial acadêmica</h3><p>Como administrador geral, autorize explicitamente uma pessoa para gerir o Acadêmico. Isso não concede poderes administrativos gerais.</p><select value={profileId} onChange={e=>setProfileId(e.target.value)}><option value="">Selecione um membro da comunidade</option>{members.map(m=><option key={m.id} value={m.id}>{m.name} · @{m.username}</option>)}</select><button disabled={!profileId} onClick={async()=>{try{await api('/api/academic/admin/setup/academic-admin',json({profileId}));window.location.reload()}catch(e){setError(e instanceof Error?e.message:'Não foi possível autorizar.')}}}>Autorizar Academic Admin</button>{error&&<small>{error}</small>}</section>}

function StudentDisciplines({disciplines,refresh}:{disciplines:Discipline[];refresh:()=>void}){
 const [pending,setPending]=useState<Discipline|null>(null);const [leaving,setLeaving]=useState(false);const [error,setError]=useState('');
 const leave=async()=>{if(!pending)return;setLeaving(true);setError('');try{await api(`/api/academic/enrollments/${pending.id}/leave`,{method:'DELETE'});setPending(null);refresh()}catch(reason){setError(reason instanceof Error?reason.message:'Não foi possível sair desta disciplina.')}finally{setLeaving(false)}};
 return <Section title="Minhas disciplinas" icon="menu_book">{disciplines.length?<div className="academic-discipline-grid academic-student-disciplines">{disciplines.map(d=><article className="academic-discipline-card" key={d.id}><a className="academic-student-discipline-link" href={`/academico/disciplinas/${d.id}`}><div className="academic-discipline-art"><MaterialIcon name="school"/></div><small>{d.code}</small><h3>{d.name}</h3><p>{disciplineTeacherLabel(d.teachers)}</p>{d.nextLesson&&<div className="academic-next"><small>Próxima aula</small><strong>{d.nextLesson.title}</strong><span>{dateLabel(d.nextLesson.startAt)}{d.nextLesson.location?` · ${d.nextLesson.location}`:''}</span></div>}</a><button type="button" className="academic-student-leave" aria-label={`Sair de ${d.name}`} onClick={()=>{setError('');setPending(d)}}>Sair</button></article>)}</div>:<Empty>Você ainda não está vinculado a nenhuma disciplina.</Empty>}{pending&&<div className="academic-confirm-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget&&!leaving)setPending(null)}}><section className="academic-confirm-dialog academic-leave-dialog" role="alertdialog" aria-modal="true" aria-labelledby="academic-student-leave-title" aria-describedby="academic-student-leave-description"><small>CONFIRMAÇÃO</small><h2 id="academic-student-leave-title">Sair da matéria?</h2><p id="academic-student-leave-description">Deseja realmente sair de <strong>{pending.name}</strong>? Você deixará de ver as atividades e os conteúdos desta matéria.</p>{error&&<p className="academic-inline-error" role="alert">{error}</p>}<div className="academic-confirm-actions"><button type="button" disabled={leaving} onClick={()=>setPending(null)}>Cancelar</button><button type="button" className="academic-confirm-delete" disabled={leaving} onClick={()=>void leave()}>{leaving?'Saindo…':'Confirmar saída'}</button></div></section></div>}</Section>;
}

function TeacherHome({ data, busy, error, submit, refresh }: { data: Item | null; busy: boolean; error: string; submit: (e: FormEvent<HTMLFormElement>, path: string, after?: () => void) => void; refresh: () => void }) {
  const [selected, setSelected] = useState('');
  const [leaving, setLeaving] = useState(false);
  const [leavePending, setLeavePending] = useState<Item | null>(null);
  const [leaveError, setLeaveError] = useState('');
  const owned = (data?.disciplines ?? []) as Item[];
  const assignments = (data?.assignments ?? []) as Item[];
  const leaveDiscipline = async (id: string) => {
    setLeaving(true); setLeaveError('');
    try { await api(`/api/academic/teacher/disciplines/${id}`, { method: 'DELETE' }); setLeavePending(null); if (selected === id) setSelected(''); refresh(); }
    catch (reason) { setLeaveError(reason instanceof Error ? reason.message : 'Não foi possível sair desta disciplina.'); }
    finally { setLeaving(false); }
  };
  const openDiscipline = (id: string) => {
    setSelected(id);
    window.setTimeout(() => document.getElementById('teacher-discipline-details')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 40);
  };

  return <div className="academic-teacher">
    <section className="academic-hero academic-hero--teacher">
      <small>VYBE ACADÊMICO</small>
      <h2>Área do Professor</h2>
      <p>Gerencie suas aulas, avaliações e disciplinas.</p>
      <a href="/academico">Voltar para visão acadêmica</a>
    </section>
    {error && <div className="academic-inline-error" role="alert">{error}</div>}

    <div className="academic-top-cards academic-teacher-overview">
      <Section title="Próximas aulas" icon="event">
        {data?.lessons?.length ? data.lessons.slice(0, 3).map((lesson: Item) => <div className="academic-compact-row" key={lesson._id}><span><strong>{lesson.title}</strong><small>{dateLabel(lesson.startAt)} · {lesson.location || 'Local a definir'}</small></span></div>) : <Empty>Você não tem aulas próximas.</Empty>}
      </Section>
      <Section title="Atividades para corrigir" icon="assignment">
        {data?.pendingSubmissions?.length ? data.pendingSubmissions.slice(0, 3).map((submission: Item) => {
          const assignment = assignments.find((item) => String(item._id) === String(submission.assignmentId));
          return <div className="academic-compact-row academic-teacher-pending" key={submission.id}><span><strong>{submission.student?.displayName ?? 'Aluno'}</strong><small>{assignment?.title ?? 'Atividade'} · enviada {dateLabel(submission.submittedAt)}</small></span>{assignment?.disciplineId && <button type="button" onClick={() => openDiscipline(String(assignment.disciplineId))}>Corrigir</button>}</div>;
        }) : <Empty>Nenhuma entrega aguardando correção.</Empty>}
      </Section>
      <Section title="Próximas provas" icon="fact_check">
        {data?.exams?.length ? data.exams.slice(0, 3).map((exam: Item) => <div className="academic-compact-row" key={exam._id}><span><strong>{exam.title}</strong><small>{owned.find((item) => item.id === String(exam.disciplineId))?.name ?? 'Disciplina'} · {dateLabel(exam.examAt)}</small></span></div>) : <Empty>Nenhuma prova próxima.</Empty>}
      </Section>
    </div>

    <Section title="Minhas disciplinas" icon="menu_book">
      {leaveError && <p className="academic-inline-error" role="alert">{leaveError}</p>}
      {owned.length ? <div className="academic-discipline-grid academic-teacher-disciplines">{owned.map((discipline) => <article className="academic-discipline-card" key={discipline.id}><div className="academic-discipline-art"><MaterialIcon name="school"/></div><small>{discipline.code}</small><h3 title={discipline.name}>{discipline.name}</h3><div className="academic-teacher-discipline-actions">{discipline.assignedToMe && <button type="button" className="academic-leave-button" aria-label={`Sair de ${discipline.name}`} disabled={leaving} onClick={() => setLeavePending(discipline)}>{leaving ? '…' : 'Sair'}</button>}</div></article>)}</div> : <Empty>Você ainda não possui disciplinas atribuídas.</Empty>}
    </Section>
    {selected && <div id="teacher-discipline-details"><TeacherDiscipline id={selected} busy={busy} refresh={refresh}/></div>}

    <div className="academic-teacher-forms academic-teacher-actions">
      <Section title="Criar aula" icon="event"><form onSubmit={(event) => submit(event, '/api/academic/teacher/lessons', refresh)}><select name="disciplineId" required><option value="">Disciplina</option>{owned.map((discipline) => <option key={discipline.id} value={discipline.id}>{discipline.name}</option>)}</select><input name="title" placeholder="Título da aula" required/><input name="startAt" type="datetime-local" required/><input name="endAt" type="datetime-local" required/><input name="location" placeholder="Sala/local"/><textarea name="description" placeholder="Descrição"/><textarea name="content" placeholder="Conteúdo da aula"/><input name="academicFile" type="file" accept=".pdf,.docx,.pptx,.xlsx,.xls,image/png,image/jpeg,image/webp"/><button disabled={busy || !owned.length}>Publicar aula</button></form></Section>
      <Section title="Criar prova" icon="fact_check"><form onSubmit={(event) => submit(event, '/api/academic/teacher/exams', refresh)}><select name="disciplineId" required><option value="">Disciplina</option>{owned.map((discipline) => <option key={discipline.id} value={discipline.id}>{discipline.name}</option>)}</select><input name="title" placeholder="Título" required/><input name="examAt" type="datetime-local" required/><input name="location" placeholder="Sala/local"/><input name="maxScore" type="number" min="0.01" step="0.1" placeholder="Nota máxima" required/><textarea name="description" placeholder="Conteúdo e instruções"/><textarea name="questionsText" placeholder="Questões da prova (uma por linha)" required maxLength={42000}/><input name="academicFile" type="file" accept=".pdf,.docx,.pptx,.xlsx,.xls,image/png,image/jpeg,image/webp"/><button disabled={busy || !owned.length}>Publicar prova</button></form></Section>
      <TeacherGrading disciplines={owned} students={(data?.students ?? []) as Item[]} busy={busy} refresh={refresh}/>
    </div>
    {leavePending && <div className="academic-confirm-backdrop" onMouseDown={event => { if (event.target === event.currentTarget && !leaving) setLeavePending(null); }}><section className="academic-confirm-dialog academic-leave-dialog" role="alertdialog" aria-modal="true" aria-labelledby="academic-leave-title" aria-describedby="academic-leave-description"><small>CONFIRMAÇÃO</small><h2 id="academic-leave-title">Sair da disciplina?</h2><p id="academic-leave-description">Você deixará de estar vinculado(a) como professor(a) de <strong>{leavePending.name}</strong> e perderá o acesso a essa disciplina na Área do Professor.</p>{leaveError && <p className="academic-inline-error" role="alert">{leaveError}</p>}<div className="academic-confirm-actions"><button type="button" disabled={leaving} onClick={() => setLeavePending(null)}>Cancelar</button><button type="button" className="academic-confirm-delete" disabled={leaving} onClick={() => void leaveDiscipline(leavePending.id)}>{leaving ? 'Saindo…' : 'Confirmar saída'}</button></div></section></div>}
  </div>;
}
function TeacherDiscipline({id,busy,refresh}:{id:string;busy:boolean;refresh:()=>void}){const [data,setData]=useState<Item|null>(null);useEffect(()=>{void api<Item>(`/api/academic/teacher/discipline/${id}`).then(setData).catch(()=>setData(null))},[id]);return <Section title={data?.discipline?.name??'Disciplina'} icon="groups">{data?.lessons?.length>0&&<div className="academic-list">{data?.lessons?.map((lesson:Item)=><form className="academic-grade-form" key={lesson._id} onSubmit={async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);await api(`/api/academic/teacher/lessons/${lesson._id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(normalizeAcademicDates(Object.fromEntries(fd.entries())))});refresh()}}><b>Editar aula: {lesson.title}</b><input name="title" defaultValue={lesson.title} required/><input name="startAt" type="datetime-local" defaultValue={dateTimeInput(lesson.startAt)} required/><input name="endAt" type="datetime-local" defaultValue={dateTimeInput(lesson.endAt)} required/><input name="location" defaultValue={lesson.location} placeholder="Sala/local"/><textarea name="description" defaultValue={lesson.description} placeholder="Descrição"/><button disabled={busy}>Salvar alterações</button></form>)}</div>}{data?.students?.length?<div className="academic-list">{data.students.map((s:Item)=><article className="academic-row" key={s.id}><Avatar name={s.name} url={s.avatarUrl}/><div><strong>{s.name}</strong><p>@{s.username}</p>{s.grades?.map((g:Item)=><small key={g.id}>{g.title}: {g.score}/{g.maxScore} · {g.feedback}</small>)}</div></article>)}</div>:<Empty>Nenhum aluno matriculado nesta disciplina.</Empty>}{data?.submissions?.map((s:Item)=><form className="academic-grade-form" key={s.id} onSubmit={async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);await api(`/api/academic/teacher/submissions/${s.id}/grade`,json(Object.fromEntries(fd.entries())));refresh()}}><b>{s.student?.displayName??'Aluno'} · entrega {dateLabel(s.submittedAt)}</b><p>{s.textContent}</p>{s.attachment?.url&&<a href={s.attachment.url}>Abrir arquivo</a>}<input name="score" type="number" min="0" step="0.1" placeholder="Nota" required/><textarea name="feedback" placeholder="Feedback"/><button disabled={busy}>Salvar correção</button></form>)}</Section>}
function TeacherGrading({disciplines,students,busy,refresh}:{disciplines:Item[];students:Item[];busy:boolean;refresh:()=>void}){const [saving,setSaving]=useState(false);const [error,setError]=useState('');const [saved,setSaved]=useState<Item|null>(null);const [scoreInput,setScoreInput]=useState('');const [maxInput,setMaxInput]=useState('');const scoreValue=Number(scoreInput.replace(',','.'));const maxValue=Number(maxInput.replace(',','.'));const hasPreview=scoreInput.trim()!==''&&maxInput.trim()!==''&&Number.isFinite(scoreValue)&&scoreValue>=0&&Number.isFinite(maxValue)&&maxValue>0;const preview=hasPreview?gradeEquivalence(scoreValue,maxValue):null;const exceedsMaximum=Boolean(preview&&scoreValue>maxValue);async function submitGrade(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget;const values=Object.fromEntries(new FormData(form).entries());const student=students.find((item)=>item.id===values.studentProfileId);setSaving(true);setError('');setSaved(null);try{const grade=await api<Item>('/api/academic/teacher/grades',json({...values,score:Number(String(values.score).replace(',','.')),maxScore:Number(String(values.maxScore).replace(',','.'))}));setSaved({grade,studentName:student?.name??'Aluno'});form.reset();setScoreInput('');setMaxInput('');refresh();}catch(reason){setError(reason instanceof Error?reason.message:'Não foi possível salvar a nota.');}finally{setSaving(false);}}return <Section title="Lançar notas" icon="bar_chart"><form className="academic-grade-form" onSubmit={(event)=>void submitGrade(event)}><select name="disciplineId" required defaultValue=""><option value="">Disciplina</option>{disciplines.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select><select name="studentProfileId" required defaultValue=""><option value="">Aluno da comunidade</option>{students.map(s=><option key={s.id} value={s.id}>{s.name} · @{s.username}</option>)}</select><div className="academic-grade-reference"><strong>Escala de notas e equivalência GPA</strong><div>{gradeScale.map(([letter,range,gpa,label])=><span key={letter}><b>{letter}</b><small>{range} · {label} · GPA {gpa}</small></span>)}</div></div><input name="title" placeholder="Avaliação" required minLength={2} maxLength={120}/><input name="score" type="text" inputMode="decimal" placeholder="Nota" required value={scoreInput} onChange={(event)=>setScoreInput(event.currentTarget.value)}/><input name="maxScore" type="text" inputMode="decimal" placeholder="Nota máxima" required value={maxInput} onChange={(event)=>setMaxInput(event.currentTarget.value)}/><div className={`academic-grade-preview${exceedsMaximum?' is-invalid':''}`} aria-live="polite">{preview? <><strong>{preview.percentage.toFixed(1).replace('.',',')}%</strong><span>Conceito {preview.letter} · {preview.description}</span><b>{preview.gpa.toFixed(1).replace('.',',')} pontos GPA</b></>:<span>Informe a nota e a nota máxima para ver o conceito e o GPA.</span>}{exceedsMaximum&&<small>A nota obtida não pode ultrapassar a nota máxima.</small>}</div><textarea name="feedback" placeholder="Feedback individual" maxLength={3000}/><button disabled={saving||busy||!disciplines.length||!students.length||exceedsMaximum}>{saving?'Salvando…':'Salvar nota'}</button>{error&&<p className="academic-inline-error" role="alert">{error}</p>}{saved&&<p className="academic-success" role="status">Nota salva para {saved.studentName}. Ela já está disponível na aba Notas desse aluno.</p>}</form></Section>}

function AdminHome({disciplines,members,busy,error,submit,refresh}:{disciplines:Discipline[];members:Item[];busy:boolean;error:string;submit:(e:FormEvent<HTMLFormElement>,path:string,after?:()=>void)=>void;refresh:()=>void}){
 const [member,setMember]=useState('');
 const [memberSearch,setMemberSearch]=useState('');
 const [role,setRole]=useState<Role>('STUDENT');
 const [selectedDisciplineIds,setSelectedDisciplineIds]=useState<string[]>([]);
 const [deleting,setDeleting]=useState('');
 const [disciplineToDelete,setDisciplineToDelete]=useState<Discipline|null>(null);
 const [deleteError,setDeleteError]=useState('');
 const matchingMembers=members.filter(person=>`${person.name} ${person.username}`.toLocaleLowerCase().includes(memberSearch.trim().replace(/^@/,'').toLocaleLowerCase()));
 const deleteDiscipline=async()=>{if(!disciplineToDelete)return;const discipline=disciplineToDelete;setDeleting(discipline.id);setDeleteError('');try{await api(`/api/academic/admin/disciplines/${discipline.id}`,{method:'DELETE'});setDisciplineToDelete(null);refresh()}catch(reason){setDeleteError(reason instanceof Error?reason.message:'Não foi possível excluir a disciplina.')}finally{setDeleting('')}};
 const roleLabel=role==='TEACHER'?'Professor(a)':role==='DIRECTOR'?'Diretor(a)':role==='ACADEMIC_ADMIN'?'ADM':'Aluno(a)';
 const toggleDiscipline=(id:string,checked:boolean)=>setSelectedDisciplineIds(current=>checked?[...new Set([...current,id])]:current.filter(item=>item!==id));
 const submitMember=(event:FormEvent<HTMLFormElement>)=>submit(event,'/api/academic/admin/members/role',()=>{setSelectedDisciplineIds([]);refresh()});
 const disciplineChoices=(legend:string)=><fieldset className="academic-discipline-checks"><legend>{legend}</legend>{disciplines.length?disciplines.map(discipline=><label key={discipline.id}><input type="checkbox" name="disciplineIds" value={discipline.id} checked={selectedDisciplineIds.includes(discipline.id)} onChange={event=>toggleDiscipline(discipline.id,event.target.checked)}/><span>{discipline.name}</span></label>):<small>Nenhuma disciplina cadastrada.</small>}</fieldset>;
 return <div className="academic-admin"><section className="academic-hero academic-hero--teacher"><small>GESTÃO ACADÊMICA</small><h2>Organize a estrutura da comunidade</h2><p>Cadastre membros, funções e disciplinas.</p><a href="/academico">Voltar para visão acadêmica</a></section>{error&&<div className="academic-inline-error">{error}</div>}
  <div className="academic-teacher-forms academic-admin-forms">
   <Section title="Cadastrar membro acadêmico" icon="person_add"><form onSubmit={submitMember}><input type="search" value={memberSearch} onChange={event=>setMemberSearch(event.target.value)} placeholder="Pesquisar por nome ou @usuário" aria-label="Pesquisar membro por nome ou usuário"/><select name="profileId" value={member} onChange={event=>setMember(event.target.value)} required><option value="">{matchingMembers.length?'Selecione um membro da comunidade':'Nenhum membro encontrado'}</option>{matchingMembers.map(person=><option key={person.id} value={person.id}>{person.name} · @{person.username}</option>)}</select><select name="role" value={role} onChange={event=>{setRole(event.target.value as Role);setSelectedDisciplineIds([])}} aria-label="Função acadêmica"><option value="TEACHER">Professor(a)</option><option value="DIRECTOR">Diretor(a)</option><option value="STUDENT">Aluno(a)</option><option value="ACADEMIC_ADMIN">ADM</option></select>{role==='STUDENT'&&disciplineChoices('Disciplinas para matrícula (selecione uma ou mais)')}{(role==='TEACHER'||role==='DIRECTOR')&&disciplineChoices('Matérias para vincular (opcional)')}<button disabled={busy||!member||(role==='STUDENT'&&!selectedDisciplineIds.length)}>{role==='STUDENT'?'Matricular aluno(a)':`Cadastrar como ${roleLabel}`}</button><small>O tipo escolhido define o acesso acadêmico desta pessoa.</small></form></Section>
   <Section title="Criar disciplina" icon="menu_book"><form onSubmit={event=>submit(event,'/api/academic/admin/disciplines',refresh)}><input name="name" placeholder="Nome da disciplina" required minLength={2} maxLength={100}/><input name="code" placeholder="Código (opcional; gerado pelo nome)" maxLength={24}/><textarea name="description" placeholder="Descrição" maxLength={1500}/><button disabled={busy}>Criar disciplina</button></form></Section>
  </div>
  <Section title="Disciplinas cadastradas" icon="menu_book">{deleteError&&<p className="academic-inline-error" role="alert">{deleteError}</p>}{disciplines.length?<div className="academic-list">{disciplines.map(discipline=><article className="academic-row academic-admin-discipline" key={discipline.id}><div><strong>{discipline.name}</strong><p>{discipline.code}</p></div><button type="button" className="academic-danger" disabled={deleting===discipline.id} onClick={()=>setDisciplineToDelete(discipline)}>Excluir disciplina</button></article>)}</div>:<Empty>Nenhuma disciplina cadastrada.</Empty>}</Section>
  {disciplineToDelete&&<div className="academic-confirm-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget&&!deleting)setDisciplineToDelete(null)}}><section className="academic-confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="academic-delete-title" aria-describedby="academic-delete-description"><span className="academic-confirm-icon"><MaterialIcon name="warning"/></span><small>CONFIRMAÇÃO</small><h2 id="academic-delete-title">Excluir disciplina?</h2><p id="academic-delete-description">A disciplina <strong>{disciplineToDelete.name}</strong> será arquivada. Aulas, atividades e provas deixarão de aparecer como ativas. Notas e registros anteriores serão preservados.</p><div className="academic-confirm-actions"><button type="button" disabled={Boolean(deleting)} onClick={()=>setDisciplineToDelete(null)}>Cancelar</button><button type="button" className="academic-confirm-delete" disabled={Boolean(deleting)} onClick={()=>void deleteDiscipline()}>{deleting?'Excluindo…':'Excluir disciplina'}</button></div></section></div>}
 </div>;
}

function DisciplineDetail({data,busy,error,submit}:{data:Item;busy:boolean;error:string;submit:(e:FormEvent<HTMLFormElement>,path:string,after?:()=>void)=>void}){const d=data.discipline;return <div className="academic-detail"><div className="academic-detail-heading"><a href="/academico/disciplinas">← Disciplinas</a><small>{d.code}</small><h2>{d.name}</h2><p>{d.description||'Aulas, materiais, atividades, provas e notas desta disciplina.'}</p></div>{error&&<div className="academic-inline-error">{error}</div>}<Section title="Aulas" icon="event">{data.lessons?.length?data.lessons.map((l:Item)=><article className="academic-row" key={l._id}><div><strong>{l.title}</strong><p>{dateLabel(l.startAt)} · {l.location||'Local a definir'}</p><small>{l.description} {l.content}</small>{l.attachment?.url&&<a href={l.attachment.url}>{l.attachment.name}</a>}</div></article>):<Empty>Nenhuma aula publicada.</Empty>}</Section><Section title="Conteúdos" icon="folder_open">{data.contents?.length?data.contents.map((c:Item)=><article className="academic-row" key={c._id}><div><strong>{c.title}</strong><p>{c.description}</p>{c.url&&<a href={c.url} target="_blank" rel="noreferrer">Abrir conteúdo</a>}{c.attachment?.url&&<a href={c.attachment.url}>{c.attachment.name}</a>}</div></article>):<Empty>Nenhum conteúdo publicado.</Empty>}</Section><Section title="Atividades" icon="assignment">{data.assignments?.length?data.assignments.map((a:Item)=><article className="academic-row" key={a._id}><div><strong>{a.title}</strong><p>Prazo: {dateLabel(a.dueAt)} · Nota máxima {a.maxScore}</p><small>{a.instructions}</small>{a.attachment?.url&&<a href={a.attachment.url}>{a.attachment.name}</a>}</div></article>):<Empty>Nenhuma atividade publicada.</Empty>}</Section><Section title="Provas" icon="fact_check">{data.exams?.length?data.exams.map((e:Item)=><article className="academic-row" key={e._id}><div><strong>{e.title}</strong><p>{dateLabel(e.examAt)} · {e.location}</p><small>{e.instructions||e.description}</small>{e.attachment?.url&&<a href={e.attachment.url}>{e.attachment.name}</a>}</div></article>):<Empty>Nenhuma prova publicada.</Empty>}</Section><Section title="Minhas notas" icon="bar_chart">{data.grades?.length?data.grades.map((g:Item)=>{const equivalent=gradeEquivalence(Number(g.score),Number(g.maxScore));return <article className="academic-grade-row" key={g.id}><div><strong>{g.title}</strong><small>{equivalent.percentage.toFixed(1).replace('.',',')}% · Conceito {equivalent.letter} · {equivalent.gpa.toFixed(1).replace('.',',')} pontos GPA</small>{g.feedback&&<small>{g.feedback}</small>}</div><b>{g.score}/{g.maxScore}</b></article>}):<Empty>Suas notas aparecerão aqui.</Empty>}</Section><Section title="Enviar atividade" icon="upload_file">{data.assignments?.length?data.assignments.map((a:Item)=><form className="academic-inline-submit" key={a._id} onSubmit={e=>submit(e,`/api/academic/assignments/${a._id}/submit`)}><strong>{a.title}</strong><textarea name="textContent" placeholder="Sua resposta em texto" maxLength={10000}/>{a.allowFile&&<input name="academicFile" type="file" accept=".pdf,.docx,.pptx,.xlsx,.xls,image/png,image/jpeg,image/webp"/>}<button disabled={busy}>Enviar entrega</button></form>):<Empty>Não há atividades abertas para entrega.</Empty>}</Section></div>}
